contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, bool asOwner) public {
        address current = c.owner();
        address caller = current;
        if (!asOwner) { caller = address(uint160(uint256(keccak256(abi.encodePacked(newOwner, uint256(1))))) | 1); if (caller == current) { caller = address(uint160(uint(current)) ^ 1); } }
        // caller must be this test contract to act; only owner is msg.sender == this
        bool reverted;
        bool success;
        if (asOwner) {
            success = c.setOwner(newOwner);
            reverted = false;
        } else {
            // only owner can call: as this contract is the owner, simulate non-owner
            // by testing that when we set owner elsewhere, subsequent call from here reverts
            c.setOwner(caller);
            address before = c.owner();
            try c.setOwner(newOwner) { reverted = false; }
            catch { reverted = true; }
            assert(reverted && c.owner() == before);
            return;
        }
        assert(success && c.owner() == newOwner);
    }
    receive() external payable {}
}

