contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, bool asOwner) public {
        require(newOwner != address(this));
        address currentOwner = c.owner();
        require(currentOwner != address(this));
        bool reverted;
        address newOwnerObserved;
        bool ret = false;
        if (asOwner) {
            // Owner can only be changed by the owner; to become owner we must already be owner,
            // which we are not. Instead test that a non-owner call reverts.
        }
        // Deciding call: made by this contract, which is never the owner on a fresh C.
        try c.setOwner(newOwner) returns (bool success) {
            reverted = false;
            ret = success;
            newOwnerObserved = c.owner();
        } catch {
            reverted = true;
            newOwnerObserved = c.owner();
        }
        if (asOwner) {
            // Unreachable as owner is the deployer, not this contract; keep assert uniform.
            assert(reverted || (ret && newOwnerObserved == newOwner));
        } else {
            assert(reverted && newOwnerObserved == currentOwner);
        }
    }
    receive() external payable {}
}

